(function(root){'use strict';
// Shared calendar logic; browser copy is generated by tools/embed-data.py.
const nameDays={'Lucie':'12-13','Karel':'11-04','Ondřej':'11-30','Jiří':'04-24','Miriam':'11-05','Zdeněk':'01-23','Vladislav':'01-18','Andrea':'09-26','Jakub':'07-25','Hynek':'02-01','Barbora':'12-04','Pavel':'06-29','Michal':'09-29','Radka':'09-14','Ladislav':'06-27','Martin':'11-11','Lubomír':'06-28','Miloslav':'12-18'};
const labels={akce:'Školní akce',volno:'Volný den',jmeniny:'Svátek učitelů',pisemka:'Písemka 1.A'};
function pragueDay(now=new Date()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
function nextDay(date){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)}
function calendarItems(teachers=[],events=[],exams=[],from='2026-08-01',to='2027-08-31'){
 const result=events.map((e,i)=>({...e,id:e.id||'event-'+i}));
 for(const e of exams)result.push({...e,id:'exam-'+e.id,examId:e.id,kind:'pisemka',title:(e.subject?e.subject+' · ':'')+e.title,time:[e.time,e.group?'Skupina '+e.group:''].filter(Boolean).join(' · ')});
 const first=Number(from.slice(0,4)),last=Math.min(Number(to.slice(0,4)),first+3);
 for(let year=first;year<=last;year++){
  const byDate=new Map();for(const t of teachers){const day=nameDays[t.first];if(!day)continue;const date=year+'-'+day;if(date<from||date>to)continue;if(!byDate.has(date))byDate.set(date,[]);byDate.get(date).push(t)}
  for(const [date,ts] of byDate)result.push({id:'nameday-'+date,date,title:'Svátek · '+ts.map(t=>t.name||t.first+' '+t.last).join(', '),kind:'jmeniny',time:'Nezapomeň popřát.',teacherIds:ts.map(t=>t.id)});
 }
 return result.filter(e=>e.date>=from&&e.date<=to).sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title,'cs'));
}
function reminderKind(e){return e.kind==='jmeniny'?'namedays':e.kind==='pisemka'?'exams':'events'}
function reminderMessage(items,date,categories){const selected=items.filter(e=>categories[reminderKind(e)]);if(!selected.length)return null;const text=selected.map(e=>e.kind==='jmeniny'?e.title:e.kind==='pisemka'?'Písemka 1.A: '+e.title:e.title+(e.time?' ('+e.time+')':''));const body=text.join(' · ');return{id:'tomorrow-'+date,title:'Zítra na Betlémské · '+Number(date.slice(8))+'. '+Number(date.slice(5,7))+'.',body:body.length>320?body.slice(0,317)+'…':body,url:'index.html#events?date='+date,kind:'calendar',count:selected.length}}
const api={nameDays,labels,pragueDay,nextDay,calendarItems,reminderKind,reminderMessage};


if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.BetlemskaCalendar=api;
})(typeof window!=='undefined'?window:globalThis);
